+  font-weight: 600;
+}
+
+.sync-log-empty {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  min-height: 220px;
+  padding: 28px;
+  border: 1px dashed var(--border-strong);
+  border-radius: 10px;
+  background: color-mix(in srgb, var(--surface) 56%, transparent);
+  color: var(--fg-muted);
+  text-align: center;
+}
+
+.sync-log-title-row + .sync-log-empty {
+  margin-top: 16px;
+}
+
+.sync-log-empty.compact {
+  min-height: 120px;
+}
+
+.sync-log-empty-mark {
+  width: 11px;
+  height: 11px;
+  margin-bottom: 12px;
+  border: 2px solid var(--state-busy-fg);
+  border-radius: 50%;
+  box-shadow: 0 0 0 5px color-mix(in srgb, var(--state-busy-fg) 10%, transparent);
+}
+
+.sync-log-empty strong {
+  color: var(--fg-secondary);
+  font-size: 13px;
+  font-weight: 600;
+}
+
+.sync-log-empty p {
+  max-width: 510px;
+  margin: 7px 0 0;
+  color: var(--fg-dim);
+  font-size: 12px;
+  line-height: 1.55;
+}
+
+@keyframes sync-pulse {
+  0%, 100% { opacity: 1; transform: scale(1); }
+  50% { opacity: 0.45; transform: scale(0.82); }
+}
+
+@media (max-width: 760px) {
+  .sync-log-summary {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+  }
+
+  .sync-event {
+    grid-template-columns: 66px 14px minmax(0, 1fr);
+    gap: 9px;
+  }
+
+  .sync-event:not(:last-child)::after {
+    left: 81.5px;
+  }
+}
+
+@media (max-width: 560px) {
+  .sync-log-hero {
+    padding: 16px;
+  }
+
+  .sync-log-summary {
+    grid-template-columns: minmax(0, 1fr);
+  }
+
+  .sync-summary-item.sync-summary-wide {
+    grid-column: span 1;
+  }
+
+  .sync-event {
+    grid-template-columns: 12px minmax(0, 1fr);
+  }
+
+  .sync-event-time {
+    grid-column: 2;
+    grid-row: 1;
+    padding: 0 0 3px;
+    text-align: left;
+  }
+
+  .sync-event-marker {
+    grid-column: 1;
+    grid-row: 2;
+    margin-top: 15px;
+  }
+
+  .sync-event-card {
+    grid-column: 2;
+    grid-row: 2;
+  }
+
+  .sync-event:not(:last-child)::after {
+    top: 37px;
+    left: 5.5px;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .sync-overall-state.running::before,
+  .sync-event.started .sync-event-marker {
+    animation: none;
+  }
+}

